 test('codeVersion() reads THIS checkout\'s real HEAD sha, resolved independently off .git/HEAD', () => {
-  assert.ok(existsSync(join(REPO_ROOT, '.git')), 'precondition: this checkout has a .git directory');
-  const head = readFileSync(join(REPO_ROOT, '.git', 'HEAD'), 'utf8').trim();
+  const dotGit = join(REPO_ROOT, '.git');
+  assert.ok(existsSync(dotGit), 'precondition: this checkout has a .git');
+  // `.git` is either a directory (plain checkout) or a `gitdir: <path>` FILE
+  // (`git worktree add` makes this checkout's own .git a pointer file) — the
+  // independent resolution below reads whichever one this root actually has,
+  // never the original dir-only assumption that threw ENOTDIR.
+  let gitFileDir;
+  if (statSync(dotGit).isDirectory()) {
+    gitFileDir = dotGit;
+  } else {
+    assert.ok(statSync(dotGit).isFile(), 'precondition: a non-directory .git is a regular file');
+    const gitfile = readFileSync(dotGit, 'utf8').trim();
+    const gm = /^gitdir:\s*(.+)$/.exec(gitfile);
+    assert.ok(gm, 'precondition: a worktree .git FILE names a `gitdir: <path>` target');
+    const target = gm[1].trim();
+    assert.ok(target.length > 0, 'precondition: the `gitdir:` target path is non-empty');
+    gitFileDir = target.startsWith('/') ? target : join(REPO_ROOT, target);
+  }
+  assert.ok(statSync(gitFileDir).isDirectory(), 'precondition: the resolved git dir really is a directory');
+
+  // branches/packed-refs are shared and live in the COMMON dir, named by this
+  // git dir's own `commondir` file (a path relative TO THIS GIT DIR) when it
+  // is a per-worktree one; a plain git dir carries no commondir and is itself.
+  const commondirPath = join(gitFileDir, 'commondir');
+  let commonDir = gitFileDir;
+  if (existsSync(commondirPath)) {
+    const rel = readFileSync(commondirPath, 'utf8').trim();
+    if (rel) commonDir = rel.startsWith('/') ? rel : join(gitFileDir, rel);
+  }
+
+  const head = readFileSync(join(gitFileDir, 'HEAD'), 'utf8').trim();
   const m = /^ref:\s*(\S+)$/.exec(head);
